UPDATE `service` SET `faqs` = '[{\"question\":\"How long does a bike battery usually last?\",\"answer\":\"A quality bike battery typically lasts 2 to 4 years depending on usage, maintenance, and regular riding.\"},{\"question\":\"Do you charge extra for doorstep bike battery installation?\",\"answer\":\"No, doorstep delivery and fitting in core Coimbatore city areas are completely free with any new battery purchase.\"},{\"question\":\"How do I know if my bike battery needs replacement?\",\"answer\":\"Common signs include dim headlights, sluggish electric self-start, clicking sounds when pressing the ignition, and horn sounding weak while idling.\"},{\"question\":\"Do you offer exchange value for my old bike battery?\",\"answer\":\"Yes, we provide an attractive scrap exchange discount on your old two-wheeler battery against your new battery purchase.\"},{\"question\":\"Which two-wheeler battery brands do you supply with warranty?\",\"answer\":\"We are authorized dealers for Amaron, Exide, Okaya, SF Sonic, and Tata Green, offering manufacturer warranties ranging from 24 to 48 months.\"}]' WHERE `id` = 1;

UPDATE `service` SET `faqs` = '[{\"question\":\"Which car battery brand is best for Indian weather?\",\"answer\":\"Amaron and Exide are the most popular and durable automotive battery brands in India, designed for high heat resistance.\"},{\"question\":\"Can I get a discount for exchanging my old car battery?\",\"answer\":\"Yes, we offer generous scrap trade-in allowances for your old car battery towards the price of the new battery.\"},{\"question\":\"How quickly can a technician reach me for doorstep car battery replacement?\",\"answer\":\"Our technicians typically reach within 30 to 45 minutes across central Coimbatore, including Tatabad, Gandhipuram, RS Puram, and Peelamedu.\"},{\"question\":\"How do I check if the problem is my battery or the alternator?\",\"answer\":\"Our technician tests both your battery voltage and alternator charging output using a digital battery analyzer before recommending replacement.\"},{\"question\":\"Do you provide a bill and warranty card with the new car battery?\",\"answer\":\"Yes, all batteries come with a GST invoice, official manufacturer warranty registration, and free installation at your home or breakdown location.\"}]' WHERE `id` = 2;

UPDATE `service` SET `faqs` = '[{\"question\":\"What size UPS do I need for a 2BHK home?\",\"answer\":\"A 900VA to 1100VA UPS with a 150Ah tubular battery is generally ideal to run 3 fans, 4 LED lights, TV, and Wi-Fi router for 3 to 5 hours.\"},{\"question\":\"How often should distilled water be topped up in home UPS batteries?\",\"answer\":\"Tubular batteries typically require distilled water checking every 3 to 6 months depending on room temperature and backup frequency.\"},{\"question\":\"What is the difference between a flat plate and a tall tubular inverter battery?\",\"answer\":\"Tall tubular batteries offer longer service life (4 to 6 years), higher temperature tolerance, and withstand frequent deep discharges much better than flat plate batteries.\"},{\"question\":\"Can you repair an existing inverter/UPS of any brand?\",\"answer\":\"Yes, we service and repair all major home UPS brands including Luminous, Microtek, Exide, V-Guard, Su-Kam, and Livguard.\"},{\"question\":\"Do you offer trade-in discounts on old home UPS systems?\",\"answer\":\"Yes, we give the best market exchange value for your old inverter and dead tubular batteries when upgrading to a new setup.\"}]' WHERE `id` = 3;

UPDATE `service` SET `faqs` = '[{\"question\":\"Do you provide AMC for existing industrial UPS systems?\",\"answer\":\"Yes, we provide Comprehensive and Non-Comprehensive AMC contracts for all industrial UPS brands and battery banks.\"},{\"question\":\"What is the response time for industrial emergency breakdown calls?\",\"answer\":\"AMC clients receive priority emergency technician dispatch within 1 to 2 hours across industrial zones in Coimbatore, Tiruppur, and Pollachi.\"},{\"question\":\"Which industries and equipment do you support with industrial power systems?\",\"answer\":\"We install and service heavy-duty UPS systems for textile spinning mills, hospitals, CNC machining units, IT data centres, and manufacturing plants across Western Tamil Nadu.\"},{\"question\":\"How often should industrial battery banks be impedance tested?\",\"answer\":\"We recommend comprehensive battery bank testing and impedance checks every quarter or as per your preventive AMC schedule to avoid sudden power drops.\"},{\"question\":\"Do you replace individual cells or the entire battery bank?\",\"answer\":\"We perform individual cell conductance and load tests first; if only specific cells are deteriorating, we advise whether cell rejuvenation or full string replacement is cost-effective.\"}]' WHERE `id` = 4;

UPDATE `service` SET `faqs` = '[{\"question\":\"Why is my inverter making a continuous beeping sound?\",\"answer\":\"Continuous beeping usually indicates low battery voltage, overload condition, or internal circuit fault.\"},{\"question\":\"Do you provide on-site inverter repair in Coimbatore?\",\"answer\":\"Yes, our mobile technicians carry common replacement parts to complete most inverter repairs at your home.\"},{\"question\":\"What causes an inverter to fail to charge the battery?\",\"answer\":\"Common causes include a blown charging fuse, blown MOSFET transistors, main PCB board issues, or a dead battery unable to accept charge.\"},{\"question\":\"Can I add a second battery to my existing single-battery inverter?\",\"answer\":\"A 12V inverter requires a single 12V battery; to use two batteries in series (24V system), you need a 24V compatible inverter model. Contact our team to check your unit.\"},{\"question\":\"How long does on-site inverter troubleshooting take?\",\"answer\":\"Most common inverter faults (fuse replacement, connection rework, charging calibration) are diagnosed and repaired on-site within 30 to 60 minutes.\"}]' WHERE `id` = 5;

UPDATE `service` SET `faqs` = '[{\"question\":\"How much roof space is required for a 3kW solar system?\",\"answer\":\"A 3kW rooftop solar power system requires approximately 250 to 300 sq. ft. of shadow-free roof area.\"},{\"question\":\"Can solar panels work during rainy days in Ooty & hill stations?\",\"answer\":\"Yes, modern monocrystalline solar panels continue to generate electricity during overcast days, though at slightly reduced efficiency.\"},{\"question\":\"What is the difference between On-Grid and Off-Grid solar systems?\",\"answer\":\"On-Grid solar connects directly to the TNEB grid via net metering to reduce power bills, while Off-Grid solar includes batteries to store power for nighttime and power outages.\"},{\"question\":\"What regular maintenance do solar panels require?\",\"answer\":\"Solar panels require periodic cleaning with soft water every 2 to 4 weeks to remove dust, plus annual electrical inspection of inverters, cabling, and earthing.\"},{\"question\":\"Do you assist with TNEB solar net-metering approvals and subsidies?\",\"answer\":\"Yes, we handle complete documentation, grid connectivity inspection, and subsidy application assistance for domestic and commercial solar setups in Tamil Nadu.\"}]' WHERE `id` = 6;

UPDATE `service` SET `faqs` = '[{\"question\":\"Can a completely drained battery be recharged?\",\"answer\":\"Yes, if the internal lead plates are intact, a bench slow-recharge can often successfully recover a deeply discharged battery.\"},{\"question\":\"How long does shop battery recharging take?\",\"answer\":\"A thorough deep slow-charge typically takes 12 to 24 hours to ensure cells absorb full electrical capacity safely.\"},{\"question\":\"How do you determine whether a battery should be recharged or replaced?\",\"answer\":\"We perform specific gravity hydrometer testing and digital cranking load tests. If cells hold specific gravity above 1.250 and pass the load test after bench charging, replacement is not needed.\"},{\"question\":\"Do you offer a standby loaner battery while mine is being charged?\",\"answer\":\"Yes, subject to availability, we provide temporary standby batteries for vehicles and home inverters so you don\'t face interruptions while your battery is in our workshop.\"},{\"question\":\"Why does white crust/corrosion build up on battery terminals?\",\"answer\":\"White powder is lead sulfate caused by acid vapor escaping during charging. We clean the terminals thoroughly, apply petroleum jelly, and test charging rates to prevent recurrence.\"}]' WHERE `id` = 7;

UPDATE `service` SET `faqs` = '[{\"question\":\"Which areas in Coimbatore do you cover for doorstep service?\",\"answer\":\"We cover Tatabad, Gandhipuram, RS Puram, Peelamedu, Saravanampatti, Saibaba Colony, Singanallur, Vadavalli, Thudiyalur, and surrounding outskirts.\"},{\"question\":\"What payment options are accepted at doorstep?\",\"answer\":\"We accept Cash, UPI (GPay, PhonePe, Paytm), and Credit/Debit cards via portable POS.\"},{\"question\":\"Is there any delivery or installation charge for doorstep battery service?\",\"answer\":\"Delivery and standard fitting are 100% free with any new battery purchase within Coimbatore city limits.\"},{\"question\":\"What if my car or bike won\'t start and needs a jump start at my location?\",\"answer\":\"Our technician carries heavy-duty jump-starter packs and booster cables to start your vehicle immediately and test the battery health on the spot.\"},{\"question\":\"How do I book a doorstep battery service appointment?\",\"answer\":\"You can book instantly by calling or sending a WhatsApp message to +91 90038 11107 with your vehicle model and location.\"}]' WHERE `id` = 8;

UPDATE `service` SET `faqs` = '[{\"question\":\"How do I claim battery warranty if an issue occurs?\",\"answer\":\"Simply call our support number with your invoice/warranty code. We provide on-site warranty inspection and hassle-free replacement.\"},{\"question\":\"What are your support hours?\",\"answer\":\"Our emergency call desk and mobile support team operate Monday to Saturday, 9AM to 10PM.\"},{\"question\":\"Do I need to visit the brand service centre for warranty issues?\",\"answer\":\"No, Kiara Battery Clinic handles the warranty inspection, paperwork, and replacement directly on your behalf, saving you the hassle of dealing with brand service centres.\"},{\"question\":\"Do you provide follow-up health checks after installing a new battery?\",\"answer\":\"Yes, we offer complimentary check-ups and terminal inspections at 6-month intervals to help you maximize your battery lifespan and performance.\"},{\"question\":\"Can I get support if my battery was purchased from another dealer?\",\"answer\":\"Yes, we provide testing, diagnosis, recharging, and maintenance services for batteries purchased anywhere, with honest advice on whether repair or warranty claim is best.\"}]' WHERE `id` = 9;